mapper.select:
SELECT id, record_date, record_type, category, amount, currency, note
FROM finance_record
WHERE user_id = #{userId}
  AND record_date BETWEEN #{from} AND #{to}
ORDER BY record_date DESC, id DESC

SELECT COALESCE(SUM(amount), 0)
FROM finance_record
WHERE user_id = #{userId} AND record_type = #{type}
  AND record_date BETWEEN #{from} AND #{to}

SELECT id, snapshot_month, cash, cny_assets, usd_assets, other_assets, note
FROM asset_snapshot
WHERE user_id = #{userId} AND snapshot_month = #{month}
